def scenario_by_id(sid):
    return next((s for s in SCENARIOS if s['id'] == sid), None)

def snapshot(sid):
    import copy
    s = copy.deepcopy(scenario_by_id(sid))
    s['policies'] = [p.copy() for p in POLICIES if p['id'] in s['policy_ids']]
    s['policy_corpus'] = [p.copy() for p in POLICIES]
    s['version'] = 'scenario-1.4-rag'
    return s
